import React from 'react';
import { HashRouter as Router, Routes, Route } from 'react-router-dom';
import HomePage from './pages/HomePage';
import ExercisePage from './pages/ExercisePage';
import NotFoundPage from './pages/NotFoundPage';
import NounsExercise from './components/NounsExercise';
import GrammarPage from './pages/GrammarPage';
import PraepositionenPage from './pages/PraepositionenPage';
import HomeworkPage from './pages/HomeworkPage';
import HomeworkCardsPage from './pages/homework/HomeworkCardsPage';
import HomeworkSet2MenuPage from './pages/homework/HomeworkSet2MenuPage';
import HomeworkSet2ExercisesPage from './pages/homework/HomeworkSet2ExercisesPage';
import HomeworkSet3Page from './pages/homework/HomeworkSet3Page';
import FesteAusdrueckePage from './pages/homework/FesteAusdrueckePage';
import HomeworkSet4Page from './pages/homework/HomeworkSet4Page';
import HomeworkSet5Page from './pages/homework/HomeworkSet5Page';
import HomeworkSet6Page from './pages/homework/HomeworkSet6Page';
import HomeworkSet7Page from './pages/homework/HomeworkSet7Page';
import HomeworkSet8Page from './pages/homework/HomeworkSet8Page';
import B2Page from './pages/B2Page';
import HorenPage from './pages/b2/HorenPage';
import LesenPage from './pages/b2/LesenPage';
import SchreibenPage from './pages/b2/SchreibenPage';
import SprechenPage from './pages/b2/SprechenPage';
import SprachbausteinePage from './pages/b2/SprachbausteinePage';
import SprachbausteineTeil1Page from './pages/b2/sprachbausteine/SprachbausteineTeil1Page';
import SprachbausteineTeil2Page from './pages/b2/sprachbausteine/SprachbausteineTeil2Page';
import HorenTeil1Page from './pages/b2/horen/HorenTeil1Page';
import HorenTeil2Page from './pages/b2/horen/HorenTeil2Page';
import HorenTeil3Page from './pages/b2/horen/HorenTeil3Page';
import HorenTeil4Page from './pages/b2/horen/HorenTeil4Page';
import LesenTeil1Page from './pages/b2/lesen/LesenTeil1Page';
import LesenTeil2Page from './pages/b2/lesen/LesenTeil2Page';
import LesenTeil3Page from './pages/b2/lesen/LesenTeil3Page';
import LesenTeil4Page from './pages/b2/lesen/LesenTeil4Page';
import BeschwerdePage from './pages/b2/schreiben/BeschwerdePage';
import PhrasesPage from './pages/PhrasesPage';
import TrainerPage from './pages/trainer/TrainerPage';
import VoiceTrainerPage from './pages/trainer/VoiceTrainerPage';
import SelfStudyPage from './pages/selfstudy/SelfStudyPage';
import SelfStudy0510Page from './pages/selfstudy/SelfStudy0510Page';
import WordTrainerPage from './pages/WordTrainerPage';
import AkkusativDativExercisePage from './pages/AkkusativDativExercisePage';
import WechselpraepositionenExercisePage from './pages/WechselpraepositionenExercisePage';
import VerbPraepExercisePage from './pages/VerbPraepExercisePage';
import GenitivExercisePage from './pages/GenitivExercisePage';
import './App.css';

function App() {
  return (
    <Router>
      <div className="App">
        <Routes>
          <Route path="/" element={<HomePage />} />
          <Route path="/grammar" element={<GrammarPage />} />
          <Route path="/grammar/praep/:mode" element={<PraepositionenPage />} />
          <Route path="/word-trainer" element={<WordTrainerPage />} />
          <Route path="/word-trainer/akkusativ-dativ" element={<AkkusativDativExercisePage />} />
          <Route path="/word-trainer/wechselpraep" element={<WechselpraepositionenExercisePage />} />
          <Route path="/word-trainer/verben-praep" element={<VerbPraepExercisePage />} />
          <Route path="/word-trainer/genitiv" element={<GenitivExercisePage />} />
          <Route path="/nouns" element={<NounsExercise />} />
          <Route path="/homework" element={<HomeworkPage />} />
          <Route path="/homework/feste-ausdruecke" element={<FesteAusdrueckePage />} />
          <Route path="/homework/set/3" element={<HomeworkSet3Page />} />
          <Route path="/homework/set/4" element={<HomeworkSet4Page />} />
          <Route path="/homework/set/5" element={<HomeworkSet5Page />} />
          <Route path="/homework/set/6" element={<HomeworkSet6Page />} />
          <Route path="/homework/set/7" element={<HomeworkSet7Page />} />
          <Route path="/homework/set/8" element={<HomeworkSet8Page />} />
          <Route path="/homework/set/:setId" element={<HomeworkCardsPage />} />
          <Route path="/homework/set/2" element={<HomeworkSet2MenuPage />} />
          <Route path="/homework/set/:setId/words" element={<HomeworkCardsPage />} />
          <Route path="/homework/set/2/exercises" element={<HomeworkSet2ExercisesPage />} />
          <Route path="/phrases" element={<PhrasesPage />} />
          <Route path="/trainer" element={<TrainerPage />} />
          <Route path="/trainer-voice" element={<VoiceTrainerPage />} />
          <Route path="/self-study" element={<SelfStudyPage />} />
          <Route path="/self-study/05-10" element={<SelfStudy0510Page />} />
          <Route path="/b2" element={<B2Page />} />
          <Route path="/b2/horen" element={<HorenPage />} />
          <Route path="/b2/horen/teil1" element={<HorenTeil1Page />} />
          <Route path="/b2/horen/teil2" element={<HorenTeil2Page />} />
          <Route path="/b2/horen/teil3" element={<HorenTeil3Page />} />
          <Route path="/b2/horen/teil4" element={<HorenTeil4Page />} />
          <Route path="/b2/lesen" element={<LesenPage />} />
          <Route path="/b2/lesen/teil1" element={<LesenTeil1Page />} />
          <Route path="/b2/lesen/teil2" element={<LesenTeil2Page />} />
          <Route path="/b2/lesen/teil3" element={<LesenTeil3Page />} />
          <Route path="/b2/lesen/teil4" element={<LesenTeil4Page />} />
          <Route path="/b2/sprachbausteine" element={<SprachbausteinePage />} />
          <Route path="/b2/sprachbausteine/teil1" element={<SprachbausteineTeil1Page />} />
          <Route path="/b2/sprachbausteine/teil2" element={<SprachbausteineTeil2Page />} />
          <Route path="/b2/schreiben" element={<SchreibenPage />} />
          <Route path="/b2/schreiben/beschwerde" element={<BeschwerdePage />} />
          <Route path="/b2/sprechen" element={<SprechenPage />} />
          <Route path="/exercise/:id" element={<ExercisePage />} />
          <Route path="*" element={<NotFoundPage />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
